def parse_duration(s):
    if not s:
        raise ValueError("Empty string")

    parts = []
    current_num = ''
    current_unit = None

    for char in s:
        if char in '0123456789':
            current_num += char
        elif char in 'dhm':
            if current_unit is not None:
                raise ValueError("Invalid format: multiple units")
            current_unit = char
            parts.append((current_num, current_unit))
            current_num = ''
        else:
            raise ValueError("Invalid character in duration string")

    if current_num or current_unit is not None:
        raise ValueError("Invalid format: incomplete number or unit")

    total_seconds = 0
    for num, unit in parts:
        if unit == 'd':
            total_seconds += int(num) * 24 * 60 * 60
        elif unit == 'h':
            total_seconds += int(num) * 60 * 60
        elif unit == 'm':
            total_seconds += int(num) * 60
        elif unit == 's':
            total_seconds += int(num)
        else:
            raise ValueError("Invalid unit")

    return total_seconds
```

